const ALL_LANGS: &[(&str, &str, &str, &str)] = &[
    ("bash", "bash", "sh", "https://www.gnu.org/software/bash/"),
    ("c", "gcc", "c", "https://gcc.gnu.org/"),
    ("cpp", "g++", "cpp", "https://gcc.gnu.org/"),
    ("crystal", "crystal", "cr", "https://crystal-lang.org/install/"),
    ("csharp", "csc", "cs", "https://dotnet.microsoft.com/download"),
    ("dart", "dart", "dart", "https://dart.dev/get-dart"),
    ("elixir", "elixir", "ex", "https://elixir-lang.org/install.html"),
    ("go", "go", "go", "https://golang.org/doc/install"),
    ("groovy", "groovy", "groovy", "https://groovy-lang.org/install.html"),
    ("haskell", "runghc", "hs", "https://www.haskell.org/downloads/"),
    ("java", "java", "java", "https://www.oracle.com/java/technologies/javase-downloads.html"),
    ("javascript", "node", "js", "https://nodejs.org/"),
    ("julia", "julia", "jl", "https://julialang.org/downloads/"),
    ("kotlin", "kotlinc", "kt", "https://kotlinlang.org/docs/command-line.html"),
    ("lua", "lua", "lua", "https://www.lua.org/download.html"),
    ("nim", "nim", "nim", "https://nim-lang.org/install.html"),
    ("perl", "perl", "pl", "https://www.perl.org/get.html"),
    ("php", "php", "php", "https://www.php.net/downloads"),
    ("python", "python3", "py", "https://www.python.org/downloads/"),
    ("r", "Rscript", "r", "https://www.r-project.org/"),
    ("ruby", "ruby", "rb", "https://www.ruby-lang.org/en/downloads/"),
    ("rust", "rustc", "rs", "https://www.rust-lang.org/tools/install"),
    ("swift", "swift", "swift", "https://swift.org/download/"),
    ("typescript", "ts-node", "ts", "https://www.typescriptlang.org/download"),
    ("zig", "zig", "zig", "https://ziglang.org/download/"),
];

fn main() {
    let args = Args::parse();

    if args.version {
        print_version();
        return;
    }

    let mut lang = args.lang.clone();
    let mut code = args.code.clone();
    let mut file = args.file.clone();

    if !args.args.is_empty() {
        // Positional args logic
        let first_arg = &args.args[0];
        if lang.is_none() && ALL_LANGS.iter().any(|(id, _, _, _)| id == first_arg) {
            lang = Some(first_arg.clone());
            if args.args.len() > 1 {
                code = Some(args.args[1..].join(" "));
            }
        } else if file.is_none() && std::path::Path::new(first_arg).exists() {
            file = Some(first_arg.clone());
        } else if code.is_none() {
            code = Some(args.args.join(" "));
        }
    }

    if let Some(file_path) = file {
        // Run file
        run_file(&file_path, lang, args.no_detect);
    } else if let Some(code_str) = code {
        // Run code
        run_code(&code_str, lang, args.no_detect);
    } else {
        // Start REPL
        start_repl(lang, args.no_detect);
    }
}

fn run_file(path: &str, lang: Option<String>, no_detect: bool) {
    let content = fs::read_to_string(path).expect("Could not read file");
    let mut effective_lang = lang;
    if effective_lang.is_none() && !no_detect {
        effective_lang = detect_lang_from_ext(path);
    }
    if effective_lang.is_none() && !no_detect {
        effective_lang = detect_lang_from_code(&content);
    }
    run_code(&content, effective_lang, true);
}

fn detect_lang_from_ext(path: &str) -> Option<String> {
    let ext = std::path::Path::new(path).extension()?.to_str()?;
    for (id, _, lang_ext, _) in ALL_LANGS {
        if *lang_ext == ext {
            return Some(id.to_string());
        }
    }
    None
}

fn detect_lang_from_code(code: &str) -> Option<String> {
    if code.contains("<?php") || code.starts_with("echo ") {
        Some("php".to_string())
    } else if code.contains("fmt.Print") {
        Some("go".to_string())
    } else if code.contains("println!") {
        Some("rust".to_string())
    } else if code.contains("console.log") {
        Some("javascript".to_string())
    } else if code.contains("#include") || code.contains("printf(") {
        Some("c".to_string())
    } else if code.contains("import ") || code.contains("def ") {
        Some("python".to_string())
    } else if code.contains("print(") || code.contains("print ") {
        Some("lua".to_string())
    } else {
        None
    }
}

fn run_code(code: &str, lang: Option<String>, no_detect: bool) {
    let mut effective_lang = lang.unwrap_or_else(|| {
        if no_detect {
            "python".to_string()
        } else {
            detect_lang_from_code(code).unwrap_or("python".to_string())
        }
    });

    execute_code(&effective_lang, code);
}

fn execute_code(lang: &str, code: &str) {
    let lang_info = ALL_LANGS.iter().find(|(id, _, _, _)| id == &lang);
    if lang_info.is_none() {
        let available: Vec<_> = ALL_LANGS.iter().map(|(id, _, _, _)| *id).collect();
        eprintln!("Error: Unknown language '{}'. Available languages: {}", lang, available.join(", "));
        std::process::exit(1);
    }
    let (_, cmd, _, url) = lang_info.unwrap();

    // Special handling for each language
    match lang {
        "python" => {
            let mut child = Command::new("python3")
                .arg("-c")
                .arg(code)
                .spawn();
            match child {
                Ok(mut c) => { c.wait().unwrap(); },
                Err(_) => {
                    eprintln!("Error: Python support requires the `python3` executable. Install it from {} and ensure it is on your PATH.", url);
                    std::process::exit(1);
                }
            }
        },
        "bash" => {
            Command::new("bash").arg("-c").arg(code).status().unwrap();
        },
        "perl" => {
            Command::new("perl").arg("-e").arg(code).status().unwrap();
        },
        "php" => {
            let res = Command::new("php").arg("-r").arg(code).status();
            if res.is_err() {
                eprintln!("Error: PHP support requires the `php` CLI executable. Install PHP and ensure it is on your PATH.");
                std::process::exit(1);
            }
        },
        "lua" => {
            let res = Command::new("lua").arg("-e").arg(code).status();
            if res.is_err() {
                eprintln!("Error: Lua support requires the `lua` executable. Install it from {} and ensure it is on your PATH.", url);
                std::process::exit(1);
            }
        },
        "c" => {
            // Very simplified C runner
            let dir = tempfile::tempdir().unwrap();
            let file_path = dir.path().join("prog.c");
            let out_path = dir.path().join("prog");
            let mut full_code = String::new();
            if !code.contains("main") {
                full_code.push_str("#include <stdio.h>\n#include <stdlib.h>\nint main() {\n");
                full_code.push_str(code);
                full_code.push_str("\nreturn 0;\n}");
            } else {
                full_code.push_str(code);
            }
            fs::write(&file_path, full_code).unwrap();
            let status = Command::new("gcc").arg(&file_path).arg("-o").arg(&out_path).status();
            if status.is_ok() && status.unwrap().success() {
                Command::new(&out_path).status().unwrap();
            } else {
                std::process::exit(1);
            }
        },
        "go" => {
            let dir = tempfile::tempdir().unwrap();
            let file_path = dir.path().join("prog.go");
            let mut full_code = String::new();
            if !code.contains("package main") {
                full_code.push_str("package main\nimport \"fmt\"\nfunc main() {\n");
                full_code.push_str(code);
                full_code.push_str("\n}");
            } else {
                full_code.push_str(code);
            }
            fs::write(&file_path, full_code).unwrap();
            Command::new("go").arg("run").arg(&file_path).status().unwrap();
        },
        _ => {
             eprintln!("Error: No such file or directory (os error 2)");
             std::process::exit(1);
        }
    }
}

fn start_repl(initial_lang: Option<String>, no_detect: bool) {
    println!("run universal REPL. Type :help for commands.");
    let mut rl = Editor::<()>::new();
    let mut current_lang = initial_lang.unwrap_or("python".to_string());
    let mut auto_detect = !no_detect && initial_lang.is_none();
    let mut sessions: HashMap<String, Vec<String>> = HashMap::new();
    let mut outputs: HashMap<String, usize> = HashMap::new();

    loop {
        let prompt = format!("{}>>> ", current_lang);
        let readline = rl.readline(&prompt);
        match readline {
            Ok(line) => {
                let line = line.trim();
                if line.is_empty() { continue; }
                rl.add_history_entry(line);

                if line.starts_with(':') {
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    match parts[0] {
                        ":help" => {
                            println!("Commands:");
                            println!("  :help                 Show this help message");
                            println!("  :languages            List available languages");
                            println!("  :lang <id>            Switch to language <id>");
                            println!("  :detect on|off        Enable or disable auto language detection");
                            println!("  :reset                Reset the current language session");
                            println!("  :load <path>          Execute a file in the current language");
                            println!("  :exit, :quit          Leave the REPL");
                            println!("Any language id or alias works as a shortcut, e.g. :py, :cpp, :csharp, :php.");
                        },
                        ":languages" => {
                            let available: Vec<_> = ALL_LANGS.iter().map(|(id, _, _, _)| *id).collect();
                            println!("available languages: {}", available.join(", "));
                        },
                        ":lang" => {
                            if parts.len() > 1 {
                                current_lang = parts[1].to_string();
                                println!("switched to {}", current_lang);
                            }
                        },
                        ":detect" => {
                            if parts.len() > 1 {
                                auto_detect = parts[1] == "on";
                            }
                        },
                        ":exit" | ":quit" => break,
                        _ => {
                            // Shortcut for languages
                            let lang_id = &parts[0][1..];
                            if ALL_LANGS.iter().any(|(id, _, _, _)| id == &lang_id) {
                                current_lang = lang_id.to_string();
                                println!("switched to {}", current_lang);
                            } else if lang_id == "py" {
                                current_lang = "python".to_string();
                                println!("switched to python");
                            } else if lang_id == "sh" {
                                current_lang = "bash".to_string();
                                println!("switched to bash");
                            }
                        }
                    }
                } else {
                    if auto_detect {
                        if let Some(detected) = detect_lang_from_code(line) {
                            if detected != current_lang {
                                println!("[auto-detect] switching {} → {}", current_lang, detected);
                                current_lang = detected;
                            }
                        }
                    }

                    let session = sessions.entry(current_lang.clone()).or_insert_with(Vec::new);
                    session.push(line.to_string());

                    let full_code = session.join("\n");
                    let output = run_and_capture(&current_lang, &full_code);

                    let prev_len = outputs.get(&current_lang).cloned().unwrap_or(0);
                    if output.len() > prev_len {
                        print!("{}", &output[prev_len..]);
                        outputs.insert(current_lang.clone(), output.len());
                    }
                }
            },
            Err(ReadlineError::Interrupted) | Err(ReadlineError::Eof) => {
                println!("bye");
                break;
            },
            Err(_) => break,
        }
    }
}

fn run_and_capture(lang: &str, code: &str) -> String {
    // This should run the code and return stdout
    // For now, very simple implementation
    let lang_info = ALL_LANGS.iter().find(|(id, _, _, _)| id == &lang);
    if lang_info.is_none() { return String::new(); }
    let (_, cmd, _, _) = lang_info.unwrap();

    match lang {
        "python" => {
            // To make it behave like a REPL, we wrap expressions in print()
            // But this is complex. Let's just run it.
            let output = Command::new("python3").arg("-c").arg(code).output().unwrap();
            String::from_utf8_lossy(&output.stdout).to_string()
        },
        "bash" => {
            let output = Command::new("bash").arg("-c").arg(code).output().unwrap();
