fn start_repl(initial_lang: Option<String>, no_detect: bool) {
    println!("run universal REPL. Type :help for commands.");
    let mut rl = Editor::<()>::new();
    let mut current_lang = initial_lang.unwrap_or("python".to_string());
    let mut auto_detect = !no_detect && initial_lang.is_none();
    let mut sessions: HashMap<String, Vec<String>> = HashMap::new();
    let mut outputs: HashMap<String, usize> = HashMap::new();

    loop {
        let prompt = format!("{}>>> ", current_lang);
        let readline = rl.readline(&prompt);
        match readline {
            Ok(line) => {
                let line = line.trim();
                if line.is_empty() { continue; }
                rl.add_history_entry(line);

                if line.starts_with(':') {
                    let parts: Vec<&str> = line.split_whitespace().collect();
