            Command::new("bash").arg("-c").arg(code).status().unwrap();
        },
        "perl" => {
            Command::new("perl").arg("-e").arg(code).status().unwrap();
        },
        "php" => {
            let res = Command::new("php").arg("-r").arg(code).status();
            if res.is_err() {
                eprintln!("Error: PHP support requires the `php` CLI executable. Install PHP and ensure it is on your PATH.");
                std::process::exit(1);
            }
        },
        "lua" => {
            let res = Command::new("lua").arg("-e").arg(code).status();
            if res.is_err() {
                eprintln!("Error: Lua support requires the `lua` executable. Install it from {} and ensure it is on your PATH.", url);
                std::process::exit(1);
            }
        },
        "c" => {
            // Very simplified C runner
            let dir = tempfile::tempdir().unwrap();
            let file_path = dir.path().join("prog.c");
            let out_path = dir.path().join("prog");
            let mut full_code = String::new();
            if !code.contains("main") {
                full_code.push_str("#include <stdio.h>\n#include <stdlib.h>\nint main() {\n");
                full_code.push_str(code);
                full_code.push_str("\nreturn 0;\n}");
            } else {
                full_code.push_str(code);
            }
            fs::write(&file_path, full_code).unwrap();
            let status = Command::new("gcc").arg(&file_path).arg("-o").arg(&out_path).status();
            if status.is_ok() && status.unwrap().success() {
                Command::new(&out_path).status().unwrap();
            } else {
                std::process::exit(1);
            }
        },
        "go" => {
            let dir = tempfile::tempdir().unwrap();
            let file_path = dir.path().join("prog.go");
            let mut full_code = String::new();
            if !code.contains("package main") {
                full_code.push_str("package main\nimport \"fmt\"\nfunc main() {\n");
                full_code.push_str(code);
                full_code.push_str("\n}");
            } else {
                full_code.push_str(code);
            }
            fs::write(&file_path, full_code).unwrap();
            Command::new("go").arg("run").arg(&file_path).status().unwrap();
        },
        _ => {
             eprintln!("Error: No such file or directory (os error 2)");
             std::process::exit(1);
        }
    }
}

fn start_repl(initial_lang: Option<String>, no_detect: bool) {
    println!("run universal REPL. Type :help for commands.");
    let mut rl = Editor::<()>::new();
    let mut current_lang = initial_lang.unwrap_or("python".to_string());
    let mut auto_detect = !no_detect && initial_lang.is_none();
    let mut sessions: HashMap<String, Vec<String>> = HashMap::new();
    let mut outputs: HashMap<String, usize> = HashMap::new();

    loop {
        let prompt = format!("{}>>> ", current_lang);
        let readline = rl.readline(&prompt);
        match readline {
            Ok(line) => {
                let line = line.trim();
                if line.is_empty() { continue; }
                rl.add_history_entry(line);

                if line.starts_with(':') {
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    match parts[0] {
                        ":help" => {
                            println!("Commands:");
                            println!("  :help                 Show this help message");
                            println!("  :languages            List available languages");
                            println!("  :lang <id>            Switch to language <id>");
                            println!("  :detect on|off        Enable or disable auto language detection");
                            println!("  :reset                Reset the current language session");
                            println!("  :load <path>          Execute a file in the current language");
                            println!("  :exit, :quit          Leave the REPL");
                            println!("Any language id or alias works as a shortcut, e.g. :py, :cpp, :csharp, :php.");
                        },
                        ":languages" => {
                            let available: Vec<_> = ALL_LANGS.iter().map(|(id, _, _, _)| *id).collect();
                            println!("available languages: {}", available.join(", "));
                        },
                        ":lang" => {
                            if parts.len() > 1 {
                                current_lang = parts[1].to_string();
                                println!("switched to {}", current_lang);
                            }
                        },
                        ":detect" => {
                            if parts.len() > 1 {
                                auto_detect = parts[1] == "on";
                            }
                        },
                        ":exit" | ":quit" => break,
                        _ => {
                            // Shortcut for languages
                            let lang_id = &parts[0][1..];
                            if ALL_LANGS.iter().any(|(id, _, _, _)| id == &lang_id) {
                                current_lang = lang_id.to_string();
                                println!("switched to {}", current_lang);
                            } else if lang_id == "py" {
                                current_lang = "python".to_string();
                                println!("switched to python");
                            } else if lang_id == "sh" {
                                current_lang = "bash".to_string();
                                println!("switched to bash");
                            }
                        }
                    }
                } else {
                    if auto_detect {
                        if let Some(detected) = detect_lang_from_code(line) {
                            if detected != current_lang {
                                println!("[auto-detect] switching {} → {}", current_lang, detected);
                                current_lang = detected;
                            }
                        }
                    }

                    let session = sessions.entry(current_lang.clone()).or_insert_with(Vec::new);
                    session.push(line.to_string());

                    let full_code = session.join("\n");
                    let output = run_and_capture(&current_lang, &full_code);

                    let prev_len = outputs.get(&current_lang).cloned().unwrap_or(0);
                    if output.len() > prev_len {
                        print!("{}", &output[prev_len..]);
                        outputs.insert(current_lang.clone(), output.len());
                    }
                }
            },
            Err(ReadlineError::Interrupted) | Err(ReadlineError::Eof) => {
                println!("bye");
                break;
            },
            Err(_) => break,
        }
    }
}

fn run_and_capture(lang: &str, code: &str) -> String {
    // This should run the code and return stdout
    // For now, very simple implementation
    let lang_info = ALL_LANGS.iter().find(|(id, _, _, _)| id == &lang);
    if lang_info.is_none() { return String::new(); }
    let (_, cmd, _, _) = lang_info.unwrap();

    match lang {
        "python" => {
            // To make it behave like a REPL, we wrap expressions in print()
            // But this is complex. Let's just run it.
            let output = Command::new("python3").arg("-c").arg(code).output().unwrap();
            String::from_utf8_lossy(&output.stdout).to_string()
        },
        "bash" => {
            let output = Command::new("bash").arg("-c").arg(code).output().unwrap();
            String::from_utf8_lossy(&output.stdout).to_string()
        },
        "c" => {
            let dir = tempfile::tempdir().unwrap();
            let file_path = dir.path().join("prog.c");
            let out_path = dir.path().join("prog");
            let mut full_code = String::new();
            full_code.push_str("#include <stdio.h>\n#include <stdlib.h>\n");

            let mut top_level = String::new();
            let mut main_body = String::new();
            for line in code.lines() {
                if line.trim().starts_with("#") || line.contains("{") {
                    top_level.push_str(line);
                    top_level.push('\n');
                } else {
                    main_body.push_str(line);
                    main_body.push('\n');
                }
            }

            let final_code = format!("{}\nint main() {{\n{}\nreturn 0;\n}}", top_level, main_body);
            fs::write(&file_path, final_code).unwrap();
            let status = Command::new("gcc").arg(&file_path).arg("-o").arg(&out_path).status();
            if status.is_ok() && status.unwrap().success() {
                let output = Command::new(&out_path).output().unwrap();
                String::from_utf8_lossy(&output.stdout).to_string()
            } else {
                String::new()
            }
        },
        _ => String::new()
    }
